{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Ketoconazole, the closest azole antifungal analogue (Morgan 0.5532), has a measured human oral bioavailability of 76%, directly supporting that this chemotype can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Posaconazole, a close itraconazole-class analogue (Morgan 0.5288), has an absolute oral bioavailability of 0.54–0.75 in patients, supporting high oral absorption for the query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Posaconazole delayed-release tablets show an absolute bioavailability of 0.67, demonstrating that the itraconazole/posaconazole scaffold can be well absorbed when formulated appropriately.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Voriconazole, another triazole antifungal, has an oral bioavailability of 96% in healthy adults, supporting high F for lipophilic azole antifungals.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Genaconazole, a triazole antifungal, showed an absolute oral bioavailability of 100% in healthy volunteers, further supporting high F for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Posaconazole oral suspension had an absolute bioavailability of only 0.165, showing that formulation can cause low F; however, this is formulation-specific and does not represent the solid oral form expected for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally an itraconazole-type azole antifungal. The closest analogues, ketoconazole and posaconazole, show oral bioavailability values mostly above 50% in humans, and other triazole antifungals also show high F. Although the physicochemical prior is unfavorable and the fasted state may reduce absorption for this lipophilic compound, the transferable experimental evidence from close structural analogues supports F ≥ 20%. The only low-F evidence is formulation-specific (posaconazole suspension) and does not outweigh the high-F measurements.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule under fasted conditions was provided.",
    "The formulation (capsule, tablet, or solution) is unspecified; itraconazole-type absorption can be formulation- and gastric-pH-dependent.",
    "Food effects and gastric pH dependence are not directly captured by the provided evidence records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

